function svg(ic,blob){var s='<svg class="nv'+(ic.n?' k-'+ic.n:'')+'" viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">';
 if(blob&&ic.b)s+='<path class="bl" d="'+ic.b+'"/>';
 if(blob&&ic.m){var m=ic.m,id='mk-'+ic.n;s+='<mask id="'+id+'" maskUnits="userSpaceOnUse" x="'+m.x+'" y="'+m.y+'" width="'+m.w+'" height="'+m.h+'"><image href="'+m.u+'" x="'+m.x+'" y="'+m.y+'" width="'+m.w+'" height="'+m.h+'"/></mask><rect x="'+m.x+'" y="'+m.y+'" width="'+m.w+'" height="'+m.h+'" fill="currentColor" stroke="none" mask="url(#'+id+')"/>'}
 return s+ic.d.map(function(d){return '<path d="'+d+'"/>'}).join('')+'</svg>'}

